#include <stdint.h>
// 「极乐世界」：建角时勾选、之后不可改的按角色开关。该角色在局内时：暗金掉率 ×8、套装 ×5、符文 ×12（品质比例表与宝藏表）。实现与依据见 dm_elysium.c
// 「极乐世界」(Elysium): a per-character switch checked at character creation and unchangeable afterwards. While that character is in a run: unique drop rate ×8, sets ×5, runes ×12 (quality ratio table and treasure class tables). For the implementation and its basis see dm_elysium.c
#pragma once
void dm_elysium_arm(int on);     // 建角页的勾选项调：1 = 这次建出来的角色是极乐世界角色，0 = 不是。只对紧接着的一次建角生效，用掉即清 | Called by the checkbox on the character creation page: 1 = the character created this time is an Elysium character, 0 = it is not. Applies only to the immediately following character creation and is cleared once used
int dm_elysium_active(void);     // 当前这一局是不是极乐世界角色的局（表已改） | Whether the current run is the run of an Elysium character (tables changed)
void dm_elysium_pump(void);      // 游戏主线程每帧调（dm_actions_pump） | Called every frame on the game main thread (dm_actions_pump)
void dm_elysium_stash_step(uint64_t game, uint64_t player, uint8_t *main_base);   // 游戏服务端那一侧每拍调（diag.c 读玩家状态处）：新建极乐世界角色后补齐共享仓库 | Called every tick on the game server side (where diag.c reads the player state): tops up the shared stash after a new Elysium character is created
int dm_elysium_hold(int on, int current, int maximum);   // 极乐开着且上限 > 0：返回上限。否则返回当前值。生命和法力都走这里 | Elysium on and maximum > 0: return the maximum. Otherwise return the current value. Life and mana both use this
int dm_elysium_durability(int on, int current, int loss, int *write);   // 返回掉耐久之前的当前值。write 只有极乐开着且 loss > 0 才是 1 | Returns current durability from before the loss. write is 1 only when Elysium is on and loss > 0
void dm_elysium_gold(int on, int carry, int stash, int cost, int carry_cap, int stash_cap, int *carry_out, int *stash_out, int *cost_out, int *write);   // 极乐且花费 > 0：写回花费前的数；已经不低于上限时写回上限减 1，绝不写上限。上限未知（<=0）的那一项不写，返回值仍是花费前的数。write 的 bit0 写身上、bit1 写箱内。关着或花费为 0：原样返回，write 为 0 | Elysium and cost > 0: restore the pre-cost totals; a total already at or above its cap is restored to cap-1, and the cap itself is never written. A pool whose cap is unknown (<=0) is not written, and the returned total stays at the pre-cost value. write bit0 sets carry, bit1 sets stash. Off, or cost 0: return the inputs and write 0
